const photos={"blanc":"data:image/jpeg;base64,","monte":"data:image/png;base64,","essence":"data:image/jpeg;base64,","ciel":"data:image/jpeg;base64,","aurora":"data:image/png;base64,","nova":"data:image/png;base64,"};
const models=[['blanc','Mont Blanc',''],['monte','Montevidéu','600'],['nova','Casa Nova',''],['aurora','Aurora','1100'],['essence','Aurora Essence',''],['ciel','Monte Ciel','']].map(([id,name,rate])=>({id,name,rate,units:'1',active:false,months:{}}));
let period='2026-10';const $=id=>document.getElementById(id),money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),days=p=>{const[y,m]=p.split('-').map(Number);return new Date(y,m,0).getDate()},date=d=>{const[y,m]=period.split('-').map(Number);return new Date(y,m-1,d)},percent=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';
function state(m){return m.months[period]??(m.months[period]={selected:new Set(),mode:'custom'})}function validUnits(m){return m.units!==''&&Number.isInteger(+m.units)&&+m.units>0&&+m.units<=10000}function validRate(m){return m.rate!==''&&Number.isFinite(+m.rate)&&+m.rate>=0&&+m.rate<=1000000}function valid(m){return validUnits(m)&&validRate(m)}
function totals(list,p){let units=0,sold=0,revenue=0,potential=0;for(const m of list){const u=validUnits(m)?+m.units:0,n=m.months[p]?.selected.size??0;units+=u;sold+=u*n;if(valid(m)){revenue+=u*n*(+m.rate);potential+=u*days(p)*(+m.rate)}}return{ready:list.every(valid),units,sold,revenue,potential,capacity:units*days(p),occupancy:units?sold/(units*days(p))*100:0}}
function renderModels(){$('models').innerHTML=models.map(m=>`<article data-cabin="${m.id}" class="model ${m.active?'active':''}"><label class="model-choice">${photos[m.id]?`<img class="cabin-photo" src="${photos[m.id]}" alt="Chalé ${m.name}" loading="lazy">`:`<span class="photo-placeholder"><strong>Casa Nova</strong><span>Foto em breve</span></span>`}<span class="model-caption"><input type="checkbox" data-model="${m.id}" ${m.active?'checked':''}><span><strong>${m.name}</strong><span class="selection-label">${m.active?'Selecionado':'Adicionar à simulação'}</span></span></span></label><div class="model-fields" ${m.active?'':'hidden'}><label>Unidades<input type="number" min="1" max="10000" step="1" value="${m.units}" data-units="${m.id}" inputmode="numeric"></label><label>Diária média (R$)<input type="number" min="0" max="1000000" step="0.01" value="${m.rate}" data-rate="${m.id}" placeholder="Informe" inputmode="decimal"></label></div><p class="field-error" id="error-${m.id}" hidden>Informe unidades inteiras de 1 a 10.000 e diária de R$ 0 a R$ 1.000.000.</p></article>`).join('');document.querySelectorAll('[data-model]').forEach(el=>el.onchange=()=>{models.find(m=>m.id===el.dataset.model).active=el.checked;renderModels();renderCalendars();update()});for(const f of ['units','rate'])document.querySelectorAll(`[data-${f}]`).forEach(el=>el.oninput=()=>{models.find(m=>m.id===el.dataset[f])[f]=el.value;update()})}
function applyMode(m,mode){const s=state(m);s.mode=mode;if(mode!=='custom'){s.selected.clear();for(let d=1;d<=days(period);d++)if(mode==='all'||mode==='weekend'&&[0,5,6].includes(date(d).getDay()))s.selected.add(d)}}
function renderCalendars(){const list=models.filter(m=>m.active);$('calendars').innerHTML=list.length?list.map(m=>{const s=state(m);let cells='';for(let i=0;i<date(1).getDay();i++)cells+='<span></span>';for(let d=1;d<=days(period);d++)cells+=`<button class="day ${s.selected.has(d)?'selected':''}" data-day="${d}" data-id="${m.id}" aria-pressed="${s.selected.has(d)}" aria-label="${m.name}, ${date(d).toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}">${d}</button>`;return `<article class="calendar-card"><div class="calendar-title"><h3>${m.name}</h3><span id="count-${m.id}"></span></div><p class="hint">As mesmas noites serão aplicadas a todas as unidades deste chalé.</p><div class="actions" role="group" aria-label="Período de ${m.name}">${[['weekend','Sex, sáb e dom'],['all','Mês inteiro'],['custom','Personalizado'],['clear','Limpar seleção']].map(([mode,label])=>`<button data-mode="${mode}" data-id="${m.id}" aria-pressed="${s.mode===mode}">${label}</button>`).join('')}</div><div class="weekdays" aria-hidden="true">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar">${cells}</div></article>`}).join(''):'<p class="empty">Escolha seu primeiro chalé acima. Depois, marque as noites para descobrir o potencial do seu projeto.</p>';document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>{const m=models.find(m=>m.id===el.dataset.id),s=state(m),d=+el.dataset.day;s.selected.has(d)?s.selected.delete(d):s.selected.add(d);s.mode='custom';el.classList.toggle('selected',s.selected.has(d));el.setAttribute('aria-pressed',s.selected.has(d));document.querySelectorAll(`[data-mode][data-id="${m.id}"]`).forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode==='custom'));update()});document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{applyMode(models.find(m=>m.id===el.dataset.id),el.dataset.mode);renderCalendars();update()})}
function update(){const list=models.filter(m=>m.active),t=totals(list,period);$('total').textContent=t.ready?money(t.revenue):'—';$('potential').textContent=t.ready?money(t.potential):'—';$('units').textContent=t.units;$('sold').textContent=t.sold;$('occupancy').textContent=percent(t.occupancy);$('fill').style.width=t.occupancy+'%';$('capacity').textContent=`${t.sold} de ${t.capacity} diárias disponíveis no mês`;$('status').textContent=!list.length?'Seu projeto começa com uma escolha. Selecione um chalé e descubra as possibilidades.':!t.ready?'Preencha os campos indicados para calcular a receita total.':'Esse é o potencial de receita bruta do cenário que você montou.';$('period-label').textContent=date(1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});for(const m of models){$('error-'+m.id).hidden=!m.active||valid(m);if(m.active){$('count-'+m.id).textContent=`${state(m).selected.size} noites / unidade`;document.querySelector(`[data-units="${m.id}"]`).setAttribute('aria-invalid',!validUnits(m));document.querySelector(`[data-rate="${m.id}"]`).setAttribute('aria-invalid',!validRate(m))}}$('summary').innerHTML=list.length?list.map(m=>{const n=state(m).selected.size;return `<tr><th scope="row">${m.name}</th><td>${validUnits(m)?+m.units:'—'}</td><td>${validRate(m)?money(+m.rate):'Pendente'}</td><td>${n}</td><td>${validUnits(m)?n*(+m.units):'—'}</td><td>${percent(n/days(period)*100)}</td><td>${valid(m)?money(n*(+m.units)*(+m.rate)):'Pendente'}</td></tr>`}).join(''):'<tr><td colspan="7">Nenhum modelo selecionado.</td></tr>'}
$('month').onchange=()=>{const v=$('month').value;if(!/^(19\d{2}|20\d{2}|2100)-(0[1-9]|1[0-2])$/.test(v)){$('month').value=period;return}period=v;renderCalendars();update()};renderModels();renderCalendars();update();

// Decorative cursor uses delegation because model cards are re-rendered.
(function initCabanaMotion(){if(typeof window==='undefined'||!window.matchMedia)return;const enabled=window.matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)');const cursor=document.createElement('div');cursor.className='tch-cursor';cursor.setAttribute('aria-hidden','true');document.body.append(cursor);let frame=0,x=0,y=0,target=null;function hide(){cursor.classList.remove('visible');document.documentElement.classList.remove('tch-cursor-enabled')}function paint(){frame=0;if(!enabled.matches){hide();return}const editing=target?.closest('input:not([type="checkbox"]),textarea,select');cursor.style.transform='translate3d('+x+'px,'+y+'px,0)';cursor.classList.toggle('visible',!editing);document.documentElement.classList.toggle('tch-cursor-enabled',!editing);cursor.classList.toggle('interactive',!!target?.closest('button,a,label,input[type="checkbox"]'));const card=target?.closest('.model');if(card){const rect=card.getBoundingClientRect();card.style.setProperty('--pointer-x',(x-rect.left)+'px');card.style.setProperty('--pointer-y',(y-rect.top)+'px')}}document.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||!enabled.matches){hide();return}x=e.clientX;y=e.clientY;target=e.target;if(!frame)frame=requestAnimationFrame(paint)},{passive:true});document.addEventListener('pointerdown',()=>cursor.classList.add('pressed'),{passive:true});document.addEventListener('pointerup',()=>cursor.classList.remove('pressed'),{passive:true});document.documentElement.addEventListener('pointerleave',hide);window.addEventListener('blur',hide);document.addEventListener('keydown',hide);enabled.addEventListener('change',hide);})();
